<script setup lang="ts">import { Head, Link, router } from '@inertiajs/vue3'; import { Plus, Search } from '@lucide/vue'; import { ref } from 'vue'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input'; type Purchase = { id: string; document_number: string; supplier_document_number: string | null; issued_at: string; supplier: string; total: number; balance_amount: number; receipt_status_label: string; payment_status_label: string }; const props = defineProps<{ purchases: { data: Purchase[] }; filters: { search: string }; canCreate: boolean }>(); const search=ref(props.filters.search); const apply=()=>router.get('/purchasing/purchases',{search:search.value},{preserveState:true,replace:true}); const money=(value:number)=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(value);</script>
<template><Head title="Compras" /><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header class="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><h1 class="text-2xl font-semibold">Compras</h1><p class="text-sm text-muted-foreground">Obligaciones, recepciones físicas y pagos separados.</p></div><div class="flex gap-2"><Button variant="outline" as-child><Link href="/purchasing/suppliers">Proveedores</Link></Button><Button v-if="canCreate" as-child><Link href="/purchasing/purchases/create"><Plus /> Nueva compra</Link></Button></div></header><form class="flex max-w-xl gap-2" @submit.prevent="apply"><Input v-model="search" placeholder="Documento o proveedor" /><Button type="submit" variant="outline"><Search /> Buscar</Button></form><section class="overflow-x-auto rounded-xl border bg-card"><table class="w-full text-sm"><thead class="border-b bg-muted/40 text-left"><tr><th class="px-4 py-3">Compra</th><th class="px-4 py-3">Proveedor</th><th class="px-4 py-3">Total</th><th class="px-4 py-3">Recepción</th><th class="px-4 py-3">Pago</th><th></th></tr></thead><tbody class="divide-y"><tr v-for="purchase in purchases.data" :key="purchase.id"><td class="px-4 py-3"><p class="font-medium">{{ purchase.document_number }}</p><p class="text-xs text-muted-foreground">{{ purchase.issued_at }} · {{ purchase.supplier_document_number || 'Sin factura externa' }}</p></td><td class="px-4 py-3">{{ purchase.supplier }}</td><td class="px-4 py-3"><p>{{ money(purchase.total) }}</p><p class="text-xs text-muted-foreground">Saldo {{ money(purchase.balance_amount) }}</p></td><td class="px-4 py-3">{{ purchase.receipt_status_label }}</td><td class="px-4 py-3">{{ purchase.payment_status_label }}</td><td class="px-4 py-3 text-right"><Link :href="`/purchasing/purchases/${purchase.id}`" class="font-medium text-amber-700 hover:underline">Ver</Link></td></tr></tbody></table><p v-if="purchases.data.length===0" class="p-10 text-center text-sm text-muted-foreground">No hay compras para mostrar.</p></section></main></template>
